tool_calls.arguments:
{"command":"kubectl patch pod app --patch '
{
  "spec": {
    "containers": [
      {
        "name": "writer",
        "image": "busybox:latest",
        "command": [
          "sh",
          "-c",
          "echo \\"<h1>Hello from the shared volume!</h1>\\" > /srv/index.html"
        ],
        "volumeMounts": [
          {
            "name": "shared",
            "mountPath": "/srv"
          }
        ]
      }
    ]
  }
}'"}

